window.RP_SESSION={"id":"S-4fad1d04608a","messages":[{"id":"RP-III-0112581","time":"2026-06-12T00:20:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"카악! 퉷!","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112582","time":"2026-06-12T00:22:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"시장에서 적당한 저녁거리를 살피던 아카쿠의 발치에 끓는 가래침이 떨어진다. 약간 눈살을 찌푸리며 아카쿠는 침이 날아온 쪽으로 시선을 돌렸다. 그 곳에는 약간 취기가 도는지 얼굴이 벌겋게 변한 행상인이 있었다.","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112583","time":"2026-06-12T00:23:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"뭐야, 형씨?\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112584","time":"2026-06-12T00:24:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"거, 커다란 도마뱀이 낮부터 돌아다니는데 기분이 안 찹치고 쓰나? 징그러운 것.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112585","time":"2026-06-12T00:25:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"이렇게 노골적인 적대감은 진짜 오랜만인데...?\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112586","time":"2026-06-12T00:27:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"골기아에서의 삶이 마냥 편하냐고 물어보면 분명 그렇다고 말하기는 힘들 것이다. 그야 인간 중심의 나라에서 걸어다니는 커다란 도마뱀 한마리. 사람은 응당 자신과 다른 것에 대해서 적대감을 가지기 마련이다.","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112587","time":"2026-06-12T00:28:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"처음에는 많이 당황했지만 시간이 지나면서 나름 아카쿠도 이런 상황을 잘 넘기게 되었다.","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112588","time":"2026-06-12T00:28:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"원래 도마뱀들은 낮에 자주 다녀. 밤 공기는 추워서 썩 별로거든.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112589","time":"2026-06-12T00:29:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"뭐라는거야? 그냥 썩 꺼져.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112590","time":"2026-06-12T00:30:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아니, 나는 사과 받기 전까지 여기서 안 움직일거야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112591","time":"2026-06-12T00:30:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 그렇게 말하면서 바닥에 털석 앉았다.","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112592","time":"2026-06-12T00:32:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"그러고 물건을 한참 들여다보는 것처럼 행동할거야. 그러면 손님이 아무도 안 오겠지.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112593","time":"2026-06-12T00:32:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"그렇다고 주먹이 날아오면 크게 소리지를거야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112594","time":"2026-06-12T00:33:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"이래 보여도 나 나름 길드에 소속도 되어 있고, 정식으로 망명 절차도 거친 상태야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112595","time":"2026-06-12T00:33:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"나야 조금 시장에 안 오면 되겠지만... 형씨 행상인이잖아? 여기도 잠깐 들렸다가 가는건데 장사 못 하면 입에 풀칠이라도 하겠어?\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112596","time":"2026-06-12T00:34:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아, 참고로 모험가 길드 소속이야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112597","time":"2026-06-12T00:35:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"행상인은 일어서서 몸 싸움을 벌이려다가 다시 자리에 앉았다. 말이 모험가 길드지 사실상 용병집단과 다르지 않는 사람이니까.","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112598","time":"2026-06-12T00:37:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"그렇게 한참이나 자리를 지키는 상황. 제법 체구가 있는 드라고니안이 불쾌한 분위기를 풍기면서 자리에 앉아있는 것은 썩 보기 좋은 광경이 아니었다. 자연스레 손님도 없었다.","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112599","time":"2026-06-12T00:37:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"거... 미안하오. 내가 실수했소.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112600","time":"2026-06-12T00:38:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아니, 실수가 아니지. 실수는 고의로 그런게 아닐 것 아니야. 이건 엄연한 고의적인 행동이었어. 혹시 술 좀 마셨다고 봐달라는건 아니지?\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112601","time":"2026-06-12T00:38:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"... 무슨 사과를 원하는거요?\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112602","time":"2026-06-12T00:39:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"제대로 된 사과만 하면 된다는 이야기야. 실수가 아니었던게 맞잖아.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112603","time":"2026-06-12T00:39:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"내가 데미간에 대해서 나쁜 생각을 가진 것 같소. 미안하오. 앞으로 그러지 않을테니 용서해주시오.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112604","time":"2026-06-12T00:40:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아니지, 아직도 그래. 가진 것 같다는 이야기는 별로 좋지 않아. 마치 잘 모르겠는데 일단 내가 잘못했으니 사과하는 것 같잖아.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112605","time":"2026-06-12T00:40:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"그렇게 아카쿠와 행상인은 서로 몇번의 실랑이를 벌이다가...","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112606","time":"2026-06-12T00:41:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"... 미안하오. 나는 데미간 차별주의자요. 이 사상이 잘못됐다는 것을 당신과의 대화에서 비로소 알 수 있었소. 앞으로 다른 종족을 차별하지 않고 상냥하게 모두에게 응대하도록 하겠소.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112607","time":"2026-06-12T00:41:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"좀 부족하기는 한데... 이 정도로 끝내자.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112608","time":"2026-06-12T00:42:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 그 말을 듣고서 자리에서 일어났다. 그리고 행상인의 물건 중 컵을 두개 집었다.","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112609","time":"2026-06-12T00:42:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"괴롭혔으니까 이 정도는 사갈게.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112610","time":"2026-06-12T00:43:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"뭘 하고 싶었는지 영 모르겠구만.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112611","time":"2026-06-12T00:43:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"그냥, 형씨 그러다가 오래 가기 힘들 것 같아서.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112612","time":"2026-06-12T00:43:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"무슨 소리요?\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112613","time":"2026-06-12T00:43:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"최근에 사자회가 제법 흉흉하거든. 그런식으로 다른 종족 차별하다가 큰 일이 일어날지도 모른다고 생각했지. 그냥 오지랖이야.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112614","time":"2026-06-12T00:44:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"거 참...\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112615","time":"2026-06-12T00:44:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"그러니까 착하게 살아, 형씨.\"","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112616","time":"2026-06-12T00:44:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 그대로 너털너털 자리를 떠났다.","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112617","time":"2026-06-12T00:44:00+09:00","room":"RP III","name":"아카쿠","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-96ab98d2591c"]},{"id":"RP-III-0112618","time":"2026-06-12T00:44:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
